const Database = require('better-sqlite3');
const crypto = require('crypto');
const db = new Database('/workspace/world.db');

// Find self contact
const self_contact = db.prepare(\"SELECT * FROM ts_contacts WHERE is_self = 1\").get();
console.log('Self:', JSON.stringify(self_contact));

// Find Daniel Ortiz
const daniel = db.prepare(\"SELECT * FROM ts_contacts WHERE phone_number = '+1-347-555-0169'\").get();
console.log('Daniel:', JSON.stringify(daniel));

// Check cellular status
const settings = db.prepare(\"SELECT cellular FROM ts_device_settings LIMIT 1\").get();
console.log('Cellular enabled:', settings.cellular);

// Generate UUID
const uuid = crypto.randomUUID();
console.log('UUID:', uuid);

// Insert message
const content = 'Hi Daniel, just a heads up — I wasn\\'t able to exchange the LogiTech Wireless Mouse M310 from my order for the Wireless Ergonomic Mouse since they are different products. I\\'ll be placing a new order for the Wireless Ergonomic Mouse (\\$39) instead. Wanted to keep you in the loop!';

const now = Date.now() / 1000;

const stmt = db.prepare('INSERT INTO ts_messages (message_id, sender_person_id, sender_phone_number, recipient_person_id, recipient_phone_number, content, creation_timestamp) VALUES (?, ?, ?, ?, ?, ?, ?)');
stmt.run(uuid, self_contact.person_id, self_contact.phone_number, daniel.person_id, daniel.phone_number, content, now);

console.log('Message sent! ID:', uuid);

// Verify
const msg = db.prepare('SELECT * FROM ts_messages WHERE message_id = ?').get(uuid);
console.log('Verification:', JSON.stringify(msg));
"

